{
  "criteria": [
    {
      "kind": "inclusion",
      "text": "Histologically confirmed diagnosis of invasive BCC",
      "quote": "Histologically confirmed diagnosis of invasive BCC"
    },
    {
      "kind": "inclusion",
      "text": "Patients must be deemed unlikely to benefit from further therapy with an HHI due to prior progression, intolerance, or stable disease after 9 months on HHI therapy.",
      "quote": "Patients must be deemed unlikely to benefit from further therapy with an HHI due to any of the following: a. Prior progression of disease on HHI therapy, or b. Intolerance of prior HHI therapy ... c. No better than a stable disease after 9 months on HHI therapy"
    },
    {
      "kind": "inclusion",
      "text": "At least 1 lesion that is measurable by study criteria. For Group 1: measurable lesion ≥10 mm in maximal diameter (1.5 cm in short axis for lymph nodes) per RECIST 1.1. For Group 2: measurable baseline lesion with both perpendicular diameters ≥10 mm by digital photography.",
      "quote": "At least 1 lesion that is measurable by study criteria",
      "thresholds": [
        {"test": "lesion diameter", "op": ">=", "value": 10, "unit": "mm"},
        {"test": "lymph node short axis", "op": ">=", "value": 1.5, "unit": "cm"}
      ]
    },
    {
      "kind": "inclusion",
      "text": "Eastern Cooperative Oncology Group (ECOG) performance status ≤1",
      "quote": "Eastern Cooperative Oncology Group (ECOG) performance status ≤1",
      "thresholds": [
        {"test": "ECOG performance status", "op": "<=", "value": 1}
      ]
    },
    {
      "kind": "inclusion",
      "text": "At least 18 years old",
      "quote": "At least 18 years old",
      "thresholds": [
        {"test": "age", "op": ">=", "value": 18, "unit": "years"}
      ]
    },
    {
      "kind": "inclusion",
      "text": "Hepatic function: Total bilirubin ≤3.0x ULN (or ≤3x ULN if liver metastases). Transaminases ≤3x ULN (or ≤5x ULN if liver metastases). Alkaline phosphatase ≤2.5x ULN (or ≤5x ULN if liver or bone metastases).",
      "quote": "Total bilirubin ≤3.0x upper limit of normal (ULN) (or ≤3x ULN, if liver metastases). ... Transaminases ≤3x ULN (or ≤5x ULN, if liver metastases) ... Alkaline phosphatase (ALP) ≤2.5x ULN (or ≤5x ULN, if liver or bone metastases)",
      "thresholds": [
        {"test": "total bilirubin", "op": "<=", "value": 3, "unit": "x ULN"},
        {"test": "transaminases", "op": "<=", "value": 3, "unit": "x ULN"},
        {"test": "alkaline phosphatase", "op": "<=", "value": 2.5, "unit": "x ULN"}
      ]
    },
    {
      "kind": "inclusion",
      "text": "Renal function: Serum creatinine ≤2x ULN or estimated creatinine clearance >35 mL/min (Cockcroft-Gault).",
      "quote": "Serum creatinine ≤2x ULN or estimated creatinine clearance >35 mL/min (according the method of Cockcroft and Gault)",
      "thresholds": [
        {"test": "serum creatinine", "op": "<=", "value": 2, "unit": "x ULN"},
        {"test": "creatinine clearance", "op": ">", "value": 35, "unit": "mL/min"}
      ]
    },
    {
      "kind": "inclusion",
      "text": "Creatine phosphokinase (CPK) elevation ≤ grade 2",
      "quote": "Creatine phosphokinase (CPK) (also known as CK [creatine kinase]) elevation ≤ grade 2",
      "thresholds": [
        {"test": "CPK elevation", "op": "<=", "value": 2, "unit": "grade"}
      ]
    },
    {
      "kind": "inclusion",
      "text": "Bone marrow function: Hemoglobin ≥9.0 g/dL, ANC ≥1.5 x 10^9/L, Platelet count ≥75 x 10^9/L.",
      "quote": "Hemoglobin ≥9.0 g/dL ... Absolute neutrophil count (ANC) ≥1.5 x 109/L ... Platelet count ≥75 x 109/L",
      "thresholds": [
        {"test": "hemoglobin", "op": ">=", "value": 9, "unit": "g/dL"},
        {"test": "ANC", "op": ">=", "value": 1.5, "unit": "10^9/L"},
        {"test": "platelet count", "op": ">=", "value": 75, "unit": "10^9/L"}
      ]
    },
    {
      "kind": "inclusion",
      "text": "Anticipated life expectancy >12 weeks",
      "quote": "Anticipated life expectancy >12 weeks",
      "thresholds": [
        {"test": "life expectancy", "op": ">", "value": 12, "unit": "weeks"}
      ]
    },
    {
      "kind": "inclusion",
      "text": "All patients must consent to provide archived or newly obtained tumor material for central pathology review.",
      "quote": "All patients in either group must consent to provide archived or newly obtained tumor material (either formalin-fixed, paraffin-embedded [FFPE] block or 10 unstained or stained slides) for central pathology review for confirmation of diagnosis of BCC."
    },
    {
      "kind": "inclusion",
      "text": "Group 2 only: Patients must consent to undergo biopsies of externally visible BCC lesions at specified time points.",
      "quote": "Group 2 only (unresectable locally advanced BCC): Patients must consent to undergo biopsies of externally visible BCC lesions at baseline, cycle 1 day 22 (±3 business days), at time of tumor progression, and at other time points that may be clinically indicated in the opinion of the investigator"
    },
    {
      "kind": "inclusion",
      "text": "Willing and able to comply with clinic visits and study-related procedures",
      "quote": "Willing and able to comply with clinic visits and study-related procedures"
    },
    {
      "kind": "inclusion",
      "text": "Provide signed informed consent prior to any screening procedures (with exception of brain MRI within 60 days of enrollment).",
      "quote": "Provide signed informed consent prior to any screening procedures (with the exception of brain MRI which is allowed to be obtained within 60 days of enrollment)."
    },
    {
      "kind": "inclusion",
      "text": "Group 2 only: Patients must be deemed to have unresectable disease, with surgery contraindicated per surgeon's note.",
      "quote": "Group 2 only: Patients in Group 2 must be deemed to have unresectable disease. Surgery must be deemed contraindicated in the opinion of a Mohs dermatologic surgeon, a head and neck surgeon, or plastic surgeon."
    },
    {
      "kind": "inclusion",
      "text": "Group 2 only: Patients must be deemed not appropriate for radiation therapy, meeting at least one specified criterion.",
      "quote": "Group 2 Only: Patients in Group 2 must be deemed as not appropriate for radiation therapy."
    }
  ]
}
